const clientId = body.clientId;

if (!clientId) {
  return [{ json: { success: false, error: 'INVALID_CLIENT_ID', message: 'clientId is required' } }];
}

const client = clientMapping[clientId];
if (!client) {
  return [{ json: { success: false, error: 'INVALID_CLIENT_ID', message: 'Client ID not found' } }];
}

