const client = $('Resolve Client').first().json;
const formResponse = $('Create Lead Form').first().json;
const formData = formResponse.body || formResponse;

if (!formData.id) {
  return [{
    json: {
      success: false,
      error: 'META_API_ERROR',
      message: 'Failed to create lead form: ' + JSON.stringify(formData.error || formData),
      retryable: true
    }
  }];
}

return [{
  json: {
    success: true,
    formId: formData.id,
    testLeadPassed: false,
    campaignsUpdated: 0,
    clientId: client.clientId,
    message: 'Form created successfully (ID: ' + formData.id + '). Test lead verification and campaign attachment pending — use Meta Ads Manager to attach to active campaigns. Monitor form CVR for 72 hours. Target: 15%+'
  }
}];
